package com.rikkeibank.account.service;import com.rikkeibank.account.domain.AccountType;import com.rikkeibank.account.repo.AccountTypeRepository;import com.rikkeibank.common.api.BusinessException;import org.springframework.cache.annotation.*;import org.springframework.data.domain.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.math.BigDecimal;import java.util.UUID;
@Service public class AccountTypeService{private final AccountTypeRepository repo;public AccountTypeService(AccountTypeRepository r){repo=r;}@Transactional @CachePut(value="accountTypes",key="#result.id")public AccountType create(String c,String n,BigDecimal m){if(repo.existsByCode(c))throw BusinessException.conflict("ACCOUNT_TYPE_EXISTS","Account type code exists");return repo.save(new AccountType(c,n,m));}@Cacheable(value="accountTypes",key="#id")public AccountType get(UUID id){return repo.findById(id).orElseThrow(()->BusinessException.notFound("Account type not found"));}public Page<AccountType> list(Pageable p){return repo.findAll(p);}@Transactional @CachePut(value="accountTypes",key="#id")public AccountType update(UUID id,String c,String n,BigDecimal m,boolean a){AccountType t=get(id);t.update(c,n,m,a);return t;}@Transactional @CacheEvict(value="accountTypes",key="#id")public void delete(UUID id){if(!repo.existsById(id))throw BusinessException.notFound("Account type not found");repo.deleteById(id);}}
